import {chromium} from 'playwright';import assert from 'node:assert/strict';
const prototypeUrl = new URL('../design/sourcer-desktop-prototype/dist/index.html', import.meta.url).href;
const b=await chromium.launch();const c=await b.newContext();const p=await c.newPage();const errs=[];p.on('pageerror',e=>errs.push(e.message));await p.goto(prototypeUrl);await p.evaluate(()=>localStorage.clear());await p.reload();await p.locator('[data-screen=review]').click();await p.getByRole('button',{name:'Approve for outreach'}).click();await p.locator('[data-screen="actions"]').click();assert.equal(await p.locator('.action-card').count(),1);await p.locator('.action-card button').click();assert.equal(await p.locator('.app').evaluate(n=>n.inert),true);assert.equal(await p.locator('.close').evaluate(n=>n===document.activeElement),true);await p.keyboard.press('Shift+Tab');assert.equal(await p.locator('#openLinkedIn').evaluate(n=>n===document.activeElement),true);await p.locator('#draftText').fill('Saved draft');await p.getByRole('button',{name:'Keep for later'}).click();await p.reload();await p.locator('[data-screen="actions"]').click();await p.locator('.action-card button').click();assert.equal(await p.locator('#draftText').innerText(),'Saved draft');await p.getByRole('button',{name:'Simulate completion'}).click();assert.equal(await p.locator('.action-card').count(),0);await p.locator('[data-screen="review"]').click();for(let i=0;i<5;i++)await p.getByRole('button',{name:'Pass',exact:true}).click();assert.equal(await p.locator('#reviewCount').innerText(),'0');assert.match(await p.locator('#candidateDetail').innerText(),/No candidates/);assert.deepEqual(errs,[]);const second=await c.newPage();await second.goto(prototypeUrl);
async function register(page,title){await page.locator('#newRoleButton').click();await page.locator('#newSpec').fill('A full specification for a Rust engineer building reliable production applications in London.');await page.locator('#newTitle').fill(title);await page.locator('#newLocation').fill('London');await page.locator('#newSkills').fill('Rust');await page.getByRole('button',{name:'Review tailored searches'}).click();await page.getByRole('button',{name:'Save role & continue to search',exact:true}).click();}
await register(p,'Role A');await register(second,'Role B');await second.reload();assert.deepEqual((await second.evaluate(()=>Object.keys(localStorage).filter(k=>k.startsWith('sourcer.prototype.roles.v1.record.')).map(k=>JSON.parse(localStorage.getItem(k)).title))).sort(),['Role A','Role B']);await second.locator('[data-screen=role]').click();assert.equal(await second.locator('#registeredTitle').innerText(),'Role B');await b.close();console.log('PASS queue, drafts, persistence, completion, final candidate');
